const root = document.querySelector("#app");
function localDateString(date=new Date()) {
  const y=date.getFullYear();
  const m=String(date.getMonth()+1).padStart(2,"0");
  const d=String(date.getDate()).padStart(2,"0");
  return `${y}-${m}-${d}`;
}
function shiftDate(yyyyMmDd,delta) {
  const [y,m,d]=yyyyMmDd.split("-").map(Number);
  const value=new Date(y,m-1,d,12,0,0,0);
  value.setDate(value.getDate()+delta);
  return localDateString(value);
}
function initialPage(){const path=window.location.pathname.replace(/\/$/,"");if(path==="/admin/data-quality")return "quality";if(path==="/admin/research")return "research";if(path==="/admin/workload")return "workload";return "dashboard"}
const state = { session:null, page:initialPage(), dashboard:null, participants:null, selected:null,
  tab:"overview", messages:[], observations:[], calendars:[], forecasts:[], warnings:[], careTimeline:{items:[],preferences:null}, incidents:[], curve:null,
  curveDate:localDateString(), curveError:"", toast:"", adminUsers:[], dailyReviews:[],
  researchDashboard:null, workloadDashboard:null, dataQuality:{items:[],counts:{}}, datasetSnapshots:[], evaluationRuns:[], modelComparison:{rows:[]}, parameterLearning:{calibration_runs:[],parameter_history:[],candidate_vs_active:[],residual_diagnostics:[],promotion_history:[]},
  longitudinal:null, participantEvaluation:null, participantModelComparison:null, participantOverview:null,
  careEffects:{groups:[]}, weeklyInsights:{insights:[],suppressed:[]}, workloadParticipantCode:"",
  dimensionMode:"bars", viewModes:{careEffects:"summary",profileExplicit:"summary",slowState:"summary",learnedParameters:"summary",residualDiagnostics:"summary",weeklyInsights:"summary",carePreferences:"summary",workloadResidual:"summary"},
  researchEnd:localDateString(), researchStart:shiftDate(localDateString(),-13) };

const esc = (v) => String(v ?? "").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = (v) => v ? new Date(v).toLocaleString("zh-CN", {hour12:false}) : "—";
function businessMinute(value){const parts=new Intl.DateTimeFormat("en-GB",{timeZone:state.session?.timezone||"Asia/Shanghai",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(new Date(value));const get=t=>Number(parts.find(p=>p.type===t)?.value||0);return get("hour")*60+get("minute")}
function businessDate(value){const parts=new Intl.DateTimeFormat("en-CA",{timeZone:state.session?.timezone||"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date(value));const get=t=>parts.find(p=>p.type===t)?.value||"";return `${get("year")}-${get("month")}-${get("day")}`}
function clockMinute(value){const match=/^(\d{2}):(\d{2})/.exec(String(value||""));if(!match)return null;const minute=Number(match[1])*60+Number(match[2]);return minute>=0&&minute<1440?minute:null}
const pretty = (v) => JSON.stringify(v ?? {}, null, 2);
async function api(path, options={}) {
  const headers = {"Content-Type":"application/json", ...(options.headers||{})};
  if (state.session?.csrf_token && options.method && options.method !== "GET") headers["X-CSRF-Token"] = state.session.csrf_token;
  const response = await fetch(path, {...options, headers});
  if (response.status === 401) { state.session=null; render(); throw new Error("会话已失效，请重新登录"); }
  const type = response.headers.get("content-type") || "";
  const value = type.includes("json") ? await response.json() : await response.text();
  if (!response.ok) throw new Error(value.error || `请求失败 (${response.status})`);
  return value;
}
function toast(message){ state.toast=message; render(); setTimeout(()=>{state.toast="";render()},2200); }

async function restore(){ try{state.session=await api("/admin/api/session");state.curveDate=state.session.business_date||localDateString();if(state.page==='research')await loadResearch();else if(state.page==='workload')await loadWorkload();else if(state.page==='quality')await loadQuality();else await loadDashboard();}catch{} render(); }
function loginView(){ return `<main class="login-shell"><form class="login-card" id="login-form">
  <div class="brand-mark">MF</div><h1>MindFlow Admin</h1><p class="muted">管理员可视化后台</p>
  <label class="field">用户名<input name="username" autocomplete="username" required></label>
  <label class="field">密码<input name="password" type="password" autocomplete="current-password" required></label>
  <div class="error" id="login-error"></div><button class="primary" type="submit">安全登录</button></form></main>`; }
function shell(content){ const nav=[['dashboard','总览'],['research','研究评估'],['workload','Workload'],['quality','数据质量'],['participants','用户'],['incidents','异常中心'],...(state.session.role==='superadmin'?[['admins','管理员']]:[])]; return `<div class="shell">
  <aside class="sidebar"><div class="brand"><div class="brand-mark">MF</div><div><strong>MindFlow</strong><small>Admin Console</small></div></div>
  <nav class="nav">${nav.map(([k,l])=>`<button data-page="${k}" class="${state.page===k?'active':''}"><span>${l}</span></button>`).join('')}</nav>
  <div class="sidebar-footer"><span class="muted">${esc(state.session.username)}</span><button class="secondary" id="logout">退出</button></div></aside>
  <main class="content">${content}</main>${state.toast?`<div class="toast">${esc(state.toast)}</div>`:''}</div>`; }
function metric(label,value,note=''){return `<article class="metric"><span>${label}</span><strong>${value??0}</strong><small class="muted">${note}</small></article>`}
const viewDataRegistry = new Map();
function valueText(value){if(value===null||value===undefined||value==='')return '暂无观测';if(typeof value==='boolean')return value?'是':'否';if(Array.isArray(value))return value.length?value.join('、'):'暂无观测';if(typeof value==='object')return pretty(value);return String(value)}
function numberText(value,digits=2){return value===null||value===undefined?'暂无观测':Number(value).toFixed(digits)}
function percentText(value,digits=1){return value===null||value===undefined?'暂无观测':`${(Number(value)*100).toFixed(digits)}%`}
function uncertaintyText(value){if(value===null||value===undefined)return '暂无观测';if(typeof value!=='object')return String(value);if(value.lower_95!=null&&value.upper_95!=null)return `${numberText(value.lower_95,2)}–${numberText(value.upper_95,2)}${value.method?` · ${value.method}`:''}`;if(value.standard_error!=null)return `SE ${numberText(value.standard_error,2)}`;return valueText(value)}
function renderEmptyState(message='暂无数据'){return `<div class="empty-state">${esc(message)}</div>`}
function renderField({name,label,value='',type='text',placeholder='',required=false,minWidth=false}){return `<label class="field ${minWidth?'participant-code-field':''}"><span>${esc(label)}</span><input type="${esc(type)}" name="${esc(name)}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''}></label>`}
function renderSelect({name,label,value='',options=[],required=false,note=''}){const normalized=options.map(option=>typeof option==='string'?{value:option,label:option}:option);const selected=normalized.find(item=>String(item.value)===String(value))||normalized[0];return `<label class="field select-field"><span>${esc(label)}</span><select name="${esc(name)}" title="${esc(selected?.label||value)}" data-described-select ${required?'required':''}>${normalized.map(item=>`<option value="${esc(item.value)}" ${String(item.value)===String(value)?'selected':''}>${esc(item.label)}</option>`).join('')}</select><small class="control-note" data-select-current>${esc([note,selected?.label].filter(Boolean).join(' · '))}</small></label>`}
function renderFilterBar(content,modifier=''){return `<div class="filter-bar ${modifier}">${content}</div>`}
function renderViewToggle(key){const active=state.viewModes[key]||'summary';return `<div class="view-toggle" role="group" aria-label="视图模式">${[['summary','摘要'],['fields','字段'],['json','JSON']].map(([mode,label])=>`<button type="button" class="${active===mode?'active':''}" data-view-key="${esc(key)}" data-view-mode="${mode}">${label}</button>`).join('')}</div>`}
function flattenFields(value,prefix='',rows=[]){if(value===null||typeof value!=='object'){rows.push([prefix,value]);return rows}Object.entries(value).forEach(([key,child])=>{const path=prefix?`${prefix}.${key}`:key;if(child!==null&&typeof child==='object'&&!Array.isArray(child))flattenFields(child,path,rows);else rows.push([path,child])});return rows}
function renderKeyValueGrid(value,labels={}){const rows=flattenFields(value);return rows.length?`<dl class="key-value-grid">${rows.map(([key,item])=>`<div><dt>${esc(labels[key]||key)}<small>${labels[key]?esc(key):''}</small></dt><dd>${esc(valueText(item))}</dd></div>`).join('')}</dl>`:renderEmptyState()}
function renderJsonDetails(key,value){viewDataRegistry.set(key,value);return `<details class="json-details"><summary>原始 JSON · 完整审计数据</summary><div class="json-actions"><button type="button" class="secondary" data-copy-json="${esc(key)}">Copy JSON</button></div><pre>${esc(pretty(value))}</pre></details>`}
function renderComplexObject(key,value,summary,labels={}){const mode=state.viewModes[key]||'summary';return `${renderViewToggle(key)}${mode==='summary'?summary:mode==='fields'?renderKeyValueGrid(value,labels):renderJsonDetails(key,value)}`}
function renderProgressBar(label,score,note=''){if(score===null||score===undefined)return '';return `<div class="dimension-row"><div><strong>${esc(label)}</strong><span>${Number(score).toFixed(0)}</span></div><div class="progress-track"><i style="width:${Math.max(0,Math.min(100,Number(score)))}%"></i></div>${note?`<small>${esc(note)}</small>`:''}</div>`}
function renderDataTable(columns,rows,empty='暂无数据'){return `<div class="table-wrap"><table><thead><tr>${columns.map(column=>`<th>${esc(column.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(column=>`<td>${column.render?column.render(row):esc(valueText(row[column.key]))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${columns.length}" class="empty">${esc(empty)}</td></tr>`}</tbody></table></div>`}
function participantModelSummary(){const m=state.participantModelComparison||{};return `<section class="metric-grid">${metric('当前模型',m.current_model??'current_m0')}${metric('候选模型',m.candidate_model??'—')}${metric('验证结果',m.validation_result?.passed?'通过':'未通过')}</section>`}
function modelComparisonTable(m={rows:[]}){return `<article class="card"><div class="card-head"><div><p class="eyebrow">ADMIN MODEL COMPARISON</p><h3>M0 / M1 / M2 / M3</h3></div><span>${m.run_count||0} 次运行</span></div><div class="table-wrap"><table><thead><tr><th>模型</th><th>MAE</th><th>RMSE</th><th>Coverage</th><th>Peak Error</th><th>Sample Count</th><th>Identifiability</th><th>Boundary</th><th>Promotion warnings</th><th>晋级</th></tr></thead><tbody>${(m.rows||[]).map(x=>`<tr><td>${esc(x.model_family)}</td><td>${esc(x.mae??'—')}</td><td>${esc(x.rmse??'—')}</td><td>${esc(x.coverage??'—')}</td><td>${esc(x.peak_error??'—')}</td><td>${esc(x.sample_count??0)}</td><td>${esc(x.identifiability??'—')}</td><td>${x.boundary?.boundary_clipped?'clipped':'—'}</td><td>${esc((x.promotion_warnings||[]).join(', ')||'—')}</td><td><span class="pill ${x.promotion?.passed?'ok':''}">${x.model_family==='current_m0'?'基线':x.promotion?.passed?'通过':'未通过'}</span></td></tr>`).join('')||'<tr><td colspan="10" class="empty">暂无 rolling-origin 比较结果</td></tr>'}</tbody></table></div></article>`}
function dashboardView(){ const d=state.dashboard||{}; return `<div class="page-head"><div><p class="eyebrow">OPERATIONS OVERVIEW</p><h1>运行总览</h1><p class="muted">消息、预测、预警与运行健康的一站式视图。</p></div><button class="secondary" id="refresh-dashboard">刷新</button></div>
  <section class="metric-grid">${metric('活跃用户',d.active_participants)}${metric('24h 消息',d.messages_24h)}${metric('24h 完成',d.completed_24h)}${metric('24h 异常',d.failed_24h)}${metric('待发送预警',d.pending_warnings)}${metric('已发送预警',d.sent_warnings)}${metric('日历降级',d.calendar_degraded)}${metric('运行事件',d.runtime_incidents)}</section>
  <article class="card"><h3>服务状态</h3><div class="definition"><dt>Bot 主链</dt><dd><span class="pill ok">独立运行</span></dd><dt>管理员 API / DB</dt><dd><span class="pill ok">可用</span></dd><dt>访问方式</dt><dd>建议通过 SSH 隧道访问宿主机 127.0.0.1 端口。</dd></div></article>`; }
function participantsView(){ const data=state.participants||{items:[]}; return `<div class="page-head"><div><p class="eyebrow">PARTICIPANTS</p><h1>用户</h1><p class="muted">以参与者代码为日常主标识。</p></div></div>
  <article class="card"><form id="participant-filter">${renderFilterBar(`${renderField({name:'search',label:'参与者代码',placeholder:'例如 P002（可选）',minWidth:true})}${renderSelect({name:'status',label:'状态',options:[{value:'',label:'全部状态'},'active','inactive']})}<div class="filter-action"><button class="secondary">筛选</button></div>`,'filter-bar--participant-search')}</form>
  <div class="table-wrap"><table><thead><tr><th>用户</th><th>状态</th><th>飞书</th><th>日历</th><th>画像</th><th>最近消息</th><th>Forecast</th><th>预警</th></tr></thead><tbody>
  ${(data.items||[]).map(p=>`<tr><td><button class="link-button" data-user="${esc(p.participant_code)}">${esc(p.participant_code)}</button></td><td><span class="pill ${p.status==='active'?'ok':'bad'}">${esc(p.status)}</span></td><td>${p.feishu_bound?'已绑定':'未绑定'}</td><td>${p.calendar_usable?'可用':'不可用'}</td><td>${p.profile_version??'—'} / ${p.learned_profile_version??'—'}</td><td>${fmt(p.last_message_at)}</td><td>${esc(p.last_forecast_date||'—')}</td><td>${esc(p.latest_warning_state||'—')}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">暂无用户</td></tr>'}
  </tbody></table></div><p class="muted">共 ${data.total||0} 位</p></article>`; }
const tabs=[['overview','概览'],['research','研究诊断'],['messages','消息'],['profile','画像'],['observations','观测'],['calendar','日历'],['forecast','Forecast'],['dailyreview','Daily Review'],['warnings','Warnings'],['care','Care Timeline']];
function userDetail(){ const p=state.selected; if(!p)return participantsView(); return `<div class="detail-head"><button class="back" id="back-users">← 用户列表</button><div><p class="eyebrow">PARTICIPANT</p><h1>${esc(p.participant_code)}</h1></div></div>
  <nav class="tabs">${tabs.map(([k,l])=>`<button class="tab-button ${state.tab===k?'active':''}" data-tab="${k}">${l}</button>`).join('')}</nav>${userTab()}`; }
function overviewRadar(dimensions){if(dimensions.length<3)return renderEmptyState('至少 3 个有来源的维度时才显示雷达图');const size=360,c=180,r=132,n=dimensions.length;const point=(index,ratio=1)=>{const angle=-Math.PI/2+index*2*Math.PI/n;return [c+Math.cos(angle)*r*ratio,c+Math.sin(angle)*r*ratio]};const polygon=dimensions.map((d,i)=>point(i,d.score_0_100/100).join(',')).join(' ');return `<svg class="radar" viewBox="0 0 ${size} ${size}" role="img" aria-label="用户画像维度雷达图"><polygon class="radar-grid" points="${dimensions.map((_,i)=>point(i).join(',')).join(' ')}"/><polygon class="radar-value" points="${polygon}"/>${dimensions.map((d,i)=>{const [x,y]=point(i,1.17);return `<text x="${x}" y="${y}" text-anchor="middle">${esc(d.label)}</text>`}).join('')}</svg>`}
function participantOverviewView(){const o=state.participantOverview;if(!o)return renderEmptyState('正在加载用户总览');const risk=o.risk_summary||{};const current=o.current_state||{};const model=o.current_model||{};const quality=o.data_quality||{};const behavior=o.behavior_summary||{};const dims=o.profile_dimensions||[];const levelLabel={low:'低',medium:'中',high:'高'}[risk.attention_level]||'数据不足';const dimensionBody=state.dimensionMode==='radar'?overviewRadar(dims):dims.map(d=>renderProgressBar(d.label,d.score_0_100,`${d.source_field} · ${d.normalization}${d.confidence==null?'':` · 置信度 ${percentText(d.confidence)}`}`)).join('')||renderEmptyState('暂无可可靠映射的画像维度');return `<section class="participant-hero card"><div><p class="eyebrow">PARTICIPANT OVERVIEW V2</p><h2>${esc(o.participant_code)} <span class="pill ${o.status==='active'?'ok':''}">${esc(o.status)}</span></h2><p>最近活跃：${fmt(o.last_active_at)} · Forecast：${esc(model.forecast_date||'暂无')} · 模型：${esc(model.model_family||model.algorithm_version||'暂无')}</p><p class="muted">数据覆盖：${percentText(quality.evidence_coverage)} · 个体参数版本：${model.learned_profile_version==null?'暂无':`v${esc(model.learned_profile_version)}`}</p></div><div class="attention-level level-${esc(risk.attention_level||'unknown')}"><span>当前关注等级</span><strong>${levelLabel}</strong><small>内部研究风险提示，不是诊断</small></div></section>
  <section class="metric-grid">${metric('最新压力观测',current.stress_0_10==null?'暂无观测':`${numberText(current.stress_0_10,1)}/10`,current.latest_observed_at?fmt(current.latest_observed_at):'')}${metric('今日预测峰值',risk.peak_stress==null?'暂无 Forecast':`${numberText(risk.peak_stress,1)}/10`,risk.peak_time||'')}${metric('近 7 天预警次数',risk.warning_count_7d??'暂无数据')}${metric('Daily Review 完成率',percentText(behavior.daily_review_completion_rate_14d),'近 14 日')}</section>
  <div class="overview-layout"><article class="card"><div class="card-head"><div><p class="eyebrow">MODEL PROFILE DIMENSIONS</p><h3>画像维度</h3><p class="muted">模型与数据覆盖指标，不用于心理诊断。</p></div><div class="dimension-toggle"><button type="button" data-dimension-mode="bars" class="${state.dimensionMode==='bars'?'active':''}">维度条</button><button type="button" data-dimension-mode="radar" class="${state.dimensionMode==='radar'?'active':''}">雷达图</button></div></div>${dimensionBody}<details><summary>维度来源与归一化</summary>${renderDataTable([{key:'label',label:'维度'},{key:'description',label:'定义'},{key:'score_0_100',label:'得分'},{key:'source',label:'来源'},{key:'source_field',label:'源字段'},{key:'version',label:'版本'},{key:'sample_count',label:'样本'}],dims)}</details></article><article class="card"><p class="eyebrow">SYSTEM ASSESSMENT</p><h3>基于证据的系统判断</h3><div class="assessment-list">${(o.system_assessment||[]).map(a=>`<div class="assessment ${esc(a.level)}"><p>${esc(a.message)}</p><small>证据：${esc((a.evidence_keys||[]).join(' · '))} · n=${esc(a.sample_count??'暂无')} · 置信度 ${a.confidence==null?'暂无':percentText(a.confidence)}</small></div>`).join('')||renderEmptyState()}</div></article></div>
  <article class="card"><div class="card-head"><div><p class="eyebrow">KEY PARAMETERS</p><h3>关键个体参数</h3></div><span>${o.key_parameters?.length||0} 项</span></div>${renderDataTable([{key:'parameter',label:'参数'},{key:'estimate',label:'当前值'},{key:'uncertainty',label:'不确定性',render:r=>esc(uncertaintyText(r.uncertainty))},{key:'version',label:'版本'},{key:'sample_count',label:'样本量'},{key:'validation_status',label:'验证状态'},{key:'evidence_window',label:'证据窗口'}],o.key_parameters||[],'暂无已学习参数')}</article>`}
function sparkline(values){const clean=values.map(Number).filter(Number.isFinite);if(clean.length<2)return '';const w=150,h=40,min=Math.min(...clean),max=Math.max(...clean),range=Math.max(.001,max-min);const points=clean.map((v,i)=>`${(i/(clean.length-1))*w},${h-((v-min)/range)*(h-6)-3}`).join(' ');return `<svg class="sparkline" viewBox="0 0 ${w} ${h}" aria-hidden="true"><polyline points="${points}"/></svg>`}
function profileTabV2(p){const layers=p.profile_layers||{};const explicit=layers.explicit?.data||{};const psychometrics=layers.psychometrics||[];const slow=layers.slow_state||[];const learned=layers.learned_parameters||[];const latestSlow=slow[0]||{};const slowSummary=`<section class="metric-grid compact-metrics">${metric('7日压力',latestSlow.rolling_7d_stress==null?'暂无观测':numberText(latestSlow.rolling_7d_stress,1))}${metric('7日 Workload',latestSlow.rolling_7d_workload==null?'暂无观测':numberText(latestSlow.rolling_7d_workload,1))}${metric('7日精力',latestSlow.rolling_7d_energy==null?'暂无观测':numberText(latestSlow.rolling_7d_energy,1))}${metric('恢复质量',latestSlow.recent_recovery_quality==null?'暂无观测':numberText(latestSlow.recent_recovery_quality,1))}${metric('睡眠债',latestSlow.recent_sleep_debt==null?'暂无观测':numberText(latestSlow.recent_sleep_debt,1))}</section>`;const parameterRows=learned.flatMap(item=>Object.entries(item.parameters||{}).map(([parameter,estimate])=>({parameter,estimate:typeof estimate==='object'?estimate.estimate:estimate,uncertainty:(item.uncertainty||{})[parameter],version:item.version,sample_count:item.sample_count,validation_status:item.validation_status,evidence_window:`${item.window_start||'—'}–${item.window_end||'—'}`})));return `<section class="profile-layers"><div class="two-col"><article class="card"><p class="eyebrow">LAYER A · EXPLICIT</p><h3>显式稳定画像 v${layers.explicit?.version??p.profile_version??'—'}</h3><p class="muted">每个字段保留 value / source / updated_at；这里只展示用户明确填写的 explicit 内容。</p>${renderComplexObject('profileExplicit',explicit,renderKeyValueGrid(explicit))}</article><article class="card"><p class="eyebrow">LAYER B · PSYCHOMETRICS</p><h3>标准量表与历史变化</h3>${psychometrics.length?renderDataTable([{key:'instrument_name',label:'量表'},{key:'administered_at',label:'日期',render:r=>esc(fmt(r.administered_at))},{key:'scores',label:'总分 / 分量表',render:r=>`${esc(valueText(r.scores))}${sparkline(psychometrics.filter(x=>x.instrument_name===r.instrument_name).map(x=>Object.values(x.scores||{}).find(Number.isFinite)))}`},{key:'reference_period',label:'参考周期'}],psychometrics):renderEmptyState('暂无 PSS / BRS 量表记录')}${renderJsonDetails('psychometricsRaw',psychometrics)}</article></div><div class="two-col"><article class="card"><p class="eyebrow">LAYER C · SLOW STATE</p><h3>慢变化状态</h3>${renderComplexObject('slowState',slow,slowSummary)}</article><article class="card"><p class="eyebrow">LAYER D · LEARNED PARAMETERS</p><h3>可审计学习参数</h3>${renderComplexObject('learnedParameters',learned,renderDataTable([{key:'parameter',label:'参数'},{key:'estimate',label:'当前值'},{key:'uncertainty',label:'不确定性',render:r=>esc(uncertaintyText(r.uncertainty))},{key:'version',label:'版本'},{key:'sample_count',label:'样本量'},{key:'validation_status',label:'验证状态'},{key:'evidence_window',label:'证据窗口'}],parameterRows,'暂无学习参数'))}</article></div><article class="card"><p class="eyebrow">SCHEMA / COMPATIBILITY</p><h3>画像结构调试信息</h3><p class="muted">兼容模型参数与旧画像单独展示，不归入 Explicit 心理画像。</p>${renderJsonDetails('profileCompatibility',{schema_version:layers.schema_version,legacy_compatibility:layers.legacy_compatibility})}</article></section>`}
function careTabV2(){const weekly=state.weeklyInsights||{};const preferences=state.careTimeline.preferences||{};const timeline=state.careTimeline.items||[];const weeklySummary=`<section class="metric-grid compact-metrics">${metric('可展示洞察',weekly.insights?.length??0)}${metric('证据不足抑制',weekly.suppressed?.length??0)}${metric('最小样本量',weekly.minimum_sample_count??'暂无')}</section>${renderDataTable([{key:'statement',label:'描述性结论'},{key:'sample_count',label:'样本量'},{key:'effect_estimate',label:'估计值',render:r=>esc(numberText(r.effect_estimate))},{key:'uncertainty',label:'不确定性',render:r=>esc(valueText(r.uncertainty))},{key:'evidence_type',label:'证据类型'}],weekly.insights||[],'暂无达到证据门槛的洞察')}`;return `<div class="two-col"><article class="card"><h3>Weekly Insight · Evidence Gate</h3><p class="muted">只展示达到最小样本量且带有效应估计和不确定性的个体洞察。</p>${renderComplexObject('weeklyInsights',weekly,weeklySummary)}</article><article class="card"><h3>Care 偏好学习</h3>${renderComplexObject('carePreferences',preferences,renderKeyValueGrid(preferences))}</article></div><article class="card"><div class="card-head"><div><h3>Care Timeline</h3><p class="muted">Vulnerability × Receptivity、干预、反馈和 30/60 分钟近端结果的完整追踪。</p></div></div>${timeline.map((c,index)=>`<details><summary>${fmt(c.scheduled_at)} · ${esc(c.intervention_type)} · ${esc(c.status)}</summary>${renderKeyValueGrid({vulnerability_score:c.vulnerability_score,receptivity_score:c.receptivity_score,decision_score:c.decision_score,delivery_status:c.delivery_status,sent_at:c.sent_at,user_action:c.user_action,forecast_version:c.forecast_version,template_id:c.template_id,template_version:c.template_version})}${renderJsonDetails(`careTimeline-${index}`,c)}</details>`).join('')||renderEmptyState('暂无 Care 记录')}</article>`}
function userTab(){ const p=state.selected; if(state.tab==='overview') return participantOverviewView();
  if(state.tab==='research') return `${participantModelSummary()}${participantResearchTabV2()}`;
  if(state.tab==='profile') return profileTabV2(p);
  if(state.tab==='care') return careTabV2();
  if(state.tab==='messages') return `<article class="card"><div class="card-head"><h3>BotEvent 请求轨迹</h3><span>${state.messages.length} 条</span></div>${state.messages.map(m=>`<div class="message-row"><time>${fmt(m.received_at)}</time><span class="pill ${m.error_code?'bad':'ok'}">${esc(m.status)}</span><div><div class="message-text">${esc(m.text)}</div><small>回复：${esc(m.reply_text||'—')}</small></div><button class="link-button" data-message="${esc(m.event_id)}">展开轨迹</button></div>`).join('')||'<div class="empty">暂无消息</div>'}</article>`;
  if(state.tab==='observations') return `<article class="card"><h3>状态观测</h3><div class="table-wrap"><table><thead><tr><th>时间</th><th>类型</th><th>压力</th><th>精力</th><th>活动 / 标记</th></tr></thead><tbody>${state.observations.map(o=>`<tr><td>${fmt(o.observed_at)}</td><td>${esc(o.type)}</td><td>${esc(o.payload.stress_0_10??'—')}</td><td>${esc(o.payload.energy_0_10??'—')}</td><td>${esc(o.payload.activity||pretty(o.payload))}</td></tr>`).join('')}</tbody></table></div></article>`;
  if(state.tab==='calendar') return `<article class="card"><h3>日历快照</h3>${state.calendars.map((c,index)=>`<details><summary>${esc(c.local_date)} · ${c.events.length} 项 · ${esc(c.snapshot_state||'current')}</summary><div class="provenance">revision ${esc(c.calendar_revision)}<br>最近成功 ${fmt(c.last_refresh_success_at)}<br>${esc(c.last_refresh_error_class||'')}</div>${renderDataTable([{key:'summary',label:'事件'},{key:'event_type',label:'类型'},{key:'start_time',label:'开始'},{key:'end_time',label:'结束'}],c.events||[])}${renderJsonDetails(`calendar-${index}`,c.events)}</details>`).join('')||'<div class="empty">暂无日历快照</div>'}</article>`;
  if(state.tab==='forecast') return forecastTab();
  if(state.tab==='dailyreview') return `<article class="card"><div class="card-head"><div><h3>每日回顾</h3><p class="muted">回顾反馈与回顾估计独立保存，不覆盖原始 Forecast。</p></div><button class="secondary" id="rebuild-review">按所选日期重建</button></div>${state.dailyReviews.map((r,index)=>`<details><summary>${esc(r.local_date)} · revision ${r.revision} · ${fmt(r.submitted_at)}</summary>${r.peak_consistency===false?'<div class="curve-version-warning" role="status">本次回顾峰值回答与起始/收尾值存在冲突；峰值锚点未用于曲线重建。</div>':''}<div class="definition"><dt>早晨</dt><dd>压力 ${r.start_stress} / 精力 ${r.start_energy}</dd><dt>峰值</dt><dd>压力 ${r.peak_stress} / ${esc(r.peak_period)}</dd><dt>收尾</dt><dd>压力 ${r.end_stress} / 精力 ${r.end_energy}</dd><dt>精力消耗</dt><dd>${r.energy_consumption == null ? '未填写' : esc(r.energy_consumption)}</dd><dt>主要压力源</dt><dd>${esc(r.main_stressor||'暂无观测')}</dd><dt>恢复记录</dt><dd>${esc(r.recovery_note||'暂无观测')}</dd></div>${renderJsonDetails(`dailyReview-${index}`,r)}</details>`).join('')||'<div class="empty">暂无每日回顾</div>'}</article>`;
  return `<article class="card"><h3>预警计划</h3><div class="table-wrap"><table><thead><tr><th>风险时间</th><th>等级</th><th>状态</th><th>尝试</th><th>发送</th><th>错误</th></tr></thead><tbody>${state.warnings.map(w=>`<tr><td>${fmt(w.risk_time)}</td><td>${esc(w.warning_level)}</td><td><span class="pill ${w.status==='sent'?'ok':''}">${esc(w.status)}</span></td><td>${w.attempt_count}</td><td>${fmt(w.sent_at)}</td><td>${esc(w.last_error_code||w.last_error_class||'—')}</td></tr>`).join('')}</tbody></table></div></article>`; }
function forecastHistory(){const selected=(state.forecasts||[]).filter(item=>item.local_date===state.curveDate);return `<aside class="forecast-history"><div class="card-head"><div><p class="eyebrow">VERSION HISTORY</p><h3>所选日期版本</h3></div><span>${selected.length} 条</span></div>${selected.map(item=>`<div class="forecast-version-row ${item.valid?'current':''}"><div><b>${esc(item.forecast_version)}</b><small>${fmt(item.generated_at)}</small></div><span class="pill ${item.valid?'ok':''}">${item.valid?'CURRENT':'HISTORICAL'}</span></div>`).join('')||'<div class="empty compact">暂无持久化版本</div>'}</aside>`}
function pressureCurveImage(curve){const code=encodeURIComponent(state.selected.participant_code);const localDate=encodeURIComponent(curve.local_date||state.curveDate);const version=encodeURIComponent(curve.current_forecast_version||curve.forecast_version||curve.generated_at||'current');const src=`/admin/api/participants/${code}/pressure-curve/${localDate}.png?v=${version}`;return `<figure class="forecast-chart-shell"><div class="forecast-chart-scroll"><img class="forecast-chart-image" src="${esc(src)}" alt="${esc(curve.local_date||state.curveDate)} 压力与活力趋势图"></div><figcaption>服务端依据当前持久化 Forecast 生成；日程区间、风险点和模型状态均由同一份数据绘制。</figcaption></figure>`}
function forecastTab(){const curve=state.curve;const init=curve?.initial_state||{};const currentVersion=curve?.current_forecast_version||curve?.forecast_version;const sourceVersion=curve?.retrospective_source_forecast_version;const sourceMismatch=curve?.retrospective_matches_current_forecast===false;return `<section class="forecast-page"><article class="forecast-command card"><div><p class="eyebrow">AUTHORITATIVE FORECAST</p><h2>压力与活力趋势</h2><p class="muted">只读展示当前持久化 Forecast；只有明确点击刷新才会触发重算。</p></div><div class="curve-toolbar"><button class="secondary" id="prev-day">← 前一天</button><label class="field"><span>研究日期</span><input type="date" id="curve-date" value="${esc(state.curveDate)}"></label><button class="secondary" id="next-day">后一天 →</button><button class="primary" id="load-curve">查看</button><button class="secondary" id="refresh-forecast">明确刷新 Forecast</button></div></article>
  ${state.curveError?`<article class="card forecast-empty-state"><h3>${esc(state.curveDate)} 暂无 Forecast</h3><p class="muted">${esc(state.curveError)}。Admin 不会为只读查看自动重算。</p></article>`:''}
  ${curve?`<div class="forecast-summary-grid"><article class="forecast-summary primary-summary"><span>预测峰值</span><strong>${esc(curve.analysis?.peak_stress??'—')}<small>/10</small></strong><p>${esc(curve.analysis?.peak_stress_time||'—')}</p></article><article class="forecast-summary"><span>当前版本</span><strong class="version-value">${esc(currentVersion||'—')}</strong><p>${fmt(curve.generated_at)}</p></article><article class="forecast-summary"><span>数据覆盖</span><strong>${esc(curve.point_count||curve.curve?.length||0)}<small> 点</small></strong><p>${esc(curve.curve?.[0]?.time||'—')}–${esc(curve.curve?.at(-1)?.time||'—')}</p></article><article class="forecast-summary"><span>数据状态</span><strong class="status-value">${curve.is_current?'CURRENT':'HISTORICAL'}</strong><p>${esc(curve.semantic_status||'—')}${curve.calendar_degraded?' · 日历降级':''}</p></article></div>
  ${sourceMismatch?`<div class="curve-version-warning" role="status">Daily Review 回顾估计基于 Forecast ${esc(sourceVersion||'未知版本')}，当前版本为 ${esc(currentVersion||'未知版本')}。服务端趋势图仅展示当前权威 Forecast，请按版本分别核对回顾结果。</div>`:''}
  <div class="forecast-main-grid"><article class="card forecast-visual"><div class="card-head"><div><p class="eyebrow">MODEL TRAJECTORY</p><h3>${esc(curve.local_date)} · 全日曲线</h3></div><span class="pill ok">${esc(curve.point_count||curve.curve?.length||0)} POINTS</span></div>${pressureCurveImage(curve)}</article>${forecastHistory()}</div>
  <div class="forecast-detail-grid"><article class="card"><p class="eyebrow">PROVENANCE</p><h3>Forecast 来源与初始化</h3><div class="definition"><dt>当前 Forecast</dt><dd>${esc(currentVersion||'—')}</dd><dt>Calendar revision</dt><dd>${esc(curve.calendar_revision||'—')}</dd><dt>Observation revision</dt><dd>${esc(curve.observation_revision||'—')}</dd><dt>初始化模式</dt><dd>${esc(init.mode||'—')}</dd><dt>初始压力 / 活力</dt><dd>${esc(init.stress_0_10??'模型默认')} / ${esc(init.vitality_0_10??'模型默认')}</dd><dt>初始状态 revision</dt><dd>${esc(curve.initial_state_revision||'—')}</dd></div></article><article class="card"><p class="eyebrow">AUTHORITATIVE OVERLAYS</p><h3>事件与风险窗口</h3><div class="overlay-counts"><span><b>${curve.events?.length||0}</b> Calendar Events</span><span><b>${curve.instant_observations?.length||0}</b> Observations</span><span><b>${curve.warnings?.length||0}</b> Risk Windows</span></div><div class="event-list">${(curve.analysis?.important_calendar_events||[]).slice(0,8).map(event=>`<div class="event"><b>${esc(event.time)}–${esc(event.end_time_local)}</b><span>${esc(event.summary)}</span></div>`).join('')||'<p class="muted">所选日期没有 Calendar Event。</p>'}</div></article></div>`:''}</section>`}
function researchDateToolbar(id){return `<form id="${id}">${renderFilterBar(`${renderField({name:'date_start',label:'开始日期',type:'date',value:state.researchStart,required:true})}${renderField({name:'date_end',label:'结束日期',type:'date',value:state.researchEnd,required:true})}<div class="filter-action"><button class="primary">查询</button></div>`,'filter-bar--date-range')}</form>`}
function workloadChartImage(kind,title,description,caption,meta){const params=new URLSearchParams({date_start:state.researchStart,date_end:state.researchEnd});if(state.workloadParticipantCode)params.set('participant_code',state.workloadParticipantCode);return `<article class="card diagnostic-card"><header class="chart-title-block"><p class="eyebrow">${esc(meta.eyebrow)}</p><h3>${esc(title)}</h3><p>${esc(description)}</p><div class="chart-query-meta"><span>查询范围：${esc(state.researchStart)} ～ ${esc(state.researchEnd)}</span><span>参与者：${esc(state.workloadParticipantCode||'全部参与者')}</span>${meta.detail?`<span>${esc(meta.detail)}</span>`:''}</div></header><figure class="diagnostic-figure"><div class="diagnostic-image-shell"><img src="/admin/api/research/workload/chart/${kind}.png?${params.toString()}" alt="${esc(title)}" loading="eager"></div><figcaption>${esc(caption)}</figcaption></figure></article>`}
function workloadResidualCard(sampleCount){if(sampleCount<2)return `<article class="card diagnostic-card"><header class="chart-title-block"><p class="eyebrow">RESIDUAL</p><h3>图 C · Forecast Residual</h3><p>Residual = Actual EMA - Forecast，用于观察预测偏差的方向和大小。</p></header><div class="empty-state residual-empty"><strong>Residual 暂无足够样本</strong><span>需要至少 2 个有效 EMA 匹配点</span></div></article>`;return workloadChartImage('residual','图 C · Forecast Residual','Actual EMA - Forecast，以 0 为中心观察偏差。','Residual 用于辅助判断预测偏高或偏低；样本较少时不作统计性解释。',{eyebrow:'RESIDUAL',detail:`有效匹配：n=${sampleCount}`})}
function workloadRidgeCard(appraisal){const ridge=appraisal.ridge_fit||{};const versions=appraisal.ridge_fit_by_model_version||[];const sampleCount=ridge.sample_count??versions.reduce((total,item)=>total+Number(item.sample_count||0),0);const statusLabels={insufficient_sample:'样本不足',exploratory:'探索性拟合',separated_by_workload_model_version:'按模型版本分离'};const label=statusLabels[ridge.status]||ridge.status||'暂无状态';const tone=ridge.status==='insufficient_sample'?'warning':'ok';const details=Object.fromEntries(Object.entries(ridge).filter(([key])=>!['status','sample_count'].includes(key)));return `<article class="card ridge-card"><h3>Event Appraisal Ridge 校准</h3><div class="ridge-summary"><div><span>状态</span><strong class="status-badge ${tone}" title="${esc(ridge.status||'')}">${esc(label)}</strong></div><div><span>样本数</span><strong class="ridge-sample-count">${esc(sampleCount)}</strong></div></div>${Object.keys(details).length?renderKeyValueGrid(details):'<p class="muted ridge-note">至少需要 10 个同版本有效样本才会进行探索性拟合。</p>'}</article>`}
function workloadView(){const d=state.workloadDashboard||{};const s=d.statistics||{};const appraisal=d.event_appraisal||{};const lags=s.lagged_corr||[];const hasSeries=(d.series||[]).length>0;const emaCount=(d.actual_ema||[]).length;const residualSummary=renderDataTable([{key:'workload_model_version',label:'模型版本'},{key:'group',label:'分组'},{key:'mean_residual',label:'平均残差',render:r=>esc(numberText(r.mean_residual))},{key:'sample_count',label:'样本'}],Object.values(appraisal.residual_by||{}).flat());return `<div class="page-head"><div><p class="eyebrow">WORKLOAD × STRESS</p><h1>Workload 与压力模型研究诊断</h1><p class="muted">观察任务需求、模型预测与真实自评在同一研究窗口中的关系。</p></div></div><section class="workload-semantics" aria-label="指标含义"><div><b>W(t)</b><span>由日程与事件需求派生的任务需求代理量，是模型输入，不是新的心理状态。</span></div><div><b>Forecast</b><span>模型在完整时间网格上输出的预测压力水平。</span></div><div><b>EMA</b><span>用户实际填写的压力自评，是离散观测点。</span></div></section><form id="workload-filter">${renderFilterBar(`${renderField({name:'date_start',label:'开始日期',type:'date',value:state.researchStart,required:true})}${renderField({name:'date_end',label:'结束日期',type:'date',value:state.researchEnd,required:true})}${renderField({name:'participant_code',label:'参与者代码',value:state.workloadParticipantCode,placeholder:'例如 P002（可选）',minWidth:true})}<div class="filter-action"><button class="primary">查询</button></div>`,'filter-bar--workload')}</form><section class="metric-grid">${metric('W–Forecast 相关',s.corr_workload_forecast_stress==null?'暂无观测':Number(s.corr_workload_forecast_stress).toFixed(3))}${metric('W–Actual EMA 相关',s.corr_workload_actual_stress==null?'暂无观测':Number(s.corr_workload_actual_stress).toFixed(3))}${metric('EMA 样本数',d.actual_ema?.length??'暂无数据',`匹配容差 ±${d.match_tolerance_minutes??'—'} 分钟`)}${metric('Event Appraisal',appraisal.items?.length??'暂无数据')}</section>${hasSeries?`<section class="workload-figures">${workloadChartImage('demand-vs-forecast','图 A · 任务负荷与预测压力','共享时间轴。W(t) 保持 0-1；Forecast 保持 0-10。','该图用于观察任务需求代理量与模型预测压力在时间上的同步关系，不表示因果效应。',{eyebrow:'DEMAND × FORECAST'})}${workloadChartImage('forecast-vs-ema','图 B · 预测压力与 EMA 观测','蓝线为连续预测，红点为匹配到时间网格的实际 EMA 观测。','该图用于观察 Forecast 与真实自评观测的一致性；如存在系统偏差，可进一步查看 Residual。',{eyebrow:'FORECAST × EMA',detail:`匹配容差：±${d.match_tolerance_minutes??'—'} 分钟 ｜ EMA 样本数：n=${emaCount}`})}${workloadResidualCard(emaCount)}</section>`:renderEmptyState('当前窗口暂无包含 workload 的 Forecast；刷新 Forecast 后即可显示。')}<div class="two-col"><article class="card"><h3>Lagged correlation</h3>${renderDataTable([{key:'lag_minutes',label:'Lag',render:r=>`${esc(r.lag_minutes)} min`},{key:'correlation',label:'相关',render:r=>esc(numberText(r.correlation,3))},{key:'sample_count',label:'样本'}],lags)}</article><article class="card"><h3>按 workload bin 的误差</h3>${renderDataTable([{key:'bin',label:'Workload bin'},{key:'mae',label:'MAE',render:r=>esc(numberText(r.mae))},{key:'mean_residual',label:'平均残差',render:r=>esc(numberText(r.mean_residual))},{key:'sample_count',label:'样本'}],s.mae_by_workload_bin||[])}</article></div><div class="two-col">${workloadRidgeCard(appraisal)}<article class="card"><h3>Workload residual</h3>${renderComplexObject('workloadResidual',appraisal.residual_by||{},residualSummary)}</article></div><article class="card"><h3>Calendar Event / Recovery Window 图层</h3>${renderDataTable([{key:'local_date',label:'日期'},{key:'summary',label:'事件'},{key:'event_type',label:'类型'},{key:'start_time',label:'开始'},{key:'end_time',label:'结束'}],d.calendar_events||[])}${renderJsonDetails('workloadLayers',{calendar_events:d.calendar_events,recovery_windows:d.recovery_windows})}</article>`}
function stage5View(canWrite){const p=state.parameterLearning||{};const runs=p.calibration_runs||[];const snapshotOptions=[{value:'',label:'选择数据集快照'},...state.datasetSnapshots.map(s=>({value:s.id,label:`${s.date_start}–${s.date_end} · ${s.id.slice(0,8)}`}))];return `<section class="stage5-calibration"><div class="page-head"><div><p class="eyebrow">STAGE 5 · PERSONALIZATION</p><h2>层级个体化与残差影子模型</h2><p class="muted">候选参数只有通过 14 天起始的 Rolling-Origin、四模型对比和晋级门槛后才可生效；Residual 始终保持 shadow。</p></div></div>${canWrite?`<form id="parameter-learning-create">${renderFilterBar(`${renderSelect({name:'dataset_snapshot_id',label:'数据集快照',options:snapshotOptions,required:true})}${renderField({name:'participant_code',label:'参与者代码',placeholder:'例如 P002',required:true,minWidth:true})}<div class="filter-action stage5-action"><button class="primary">训练候选参数</button></div>`,'stage5-form')}</form>`:''}<div class="two-col"><article class="card"><h3>Calibration Runs</h3>${runs.map(r=>`<details><summary>${fmt(r.created_at)} · ${esc(r.status)} · ${esc(r.participant_id)}</summary>${canWrite&&r.status==='candidate'?`<button class="primary" data-promote-parameter="${esc(r.id)}">晋级为 Active</button>`:''}${renderKeyValueGrid({minimum_data_gate:r.training_metrics?.minimum_data_gate,rolling_origin:r.validation_metrics?.rolling_origin,promotion_gate:r.validation_metrics?.promotion_gate})}${renderJsonDetails(`calibration-${r.id}`,r)}</details>`).join('')||renderEmptyState('暂无阶段 5 校准运行')}</article><article class="card"><h3>Parameter History · Candidate vs Active</h3>${renderDataTable([{key:'created_at',label:'时间',render:r=>esc(fmt(r.created_at))},{key:'status',label:'状态'},{key:'before',label:'Before',render:r=>esc(valueText(r.before))},{key:'candidate',label:'Candidate',render:r=>esc(valueText(r.candidate))},{key:'uncertainty',label:'不确定性',render:r=>esc(valueText(r.uncertainty))}],p.parameter_history||[],'暂无参数历史')}</article></div><div class="two-col"><article class="card"><h3>Residual Diagnostics</h3><p class="muted">CTSSM baseline / residual correction / final prediction，修正绝对值上限 1.0。</p>${renderComplexObject('stage5Residual',p.residual_diagnostics||[],renderDataTable([{key:'participant_id',label:'参与者'},{key:'sample_count',label:'样本'},{key:'baseline_mae',label:'Baseline MAE'},{key:'final_mae',label:'Final MAE'},{key:'status',label:'状态'}],p.residual_diagnostics||[]))}</article><article class="card"><h3>Promotion History</h3><p class="muted">每次晋级保留 before、after、metrics 和 reason。</p>${renderComplexObject('promotionHistory',p.promotion_history||[],renderDataTable([{key:'created_at',label:'时间',render:r=>esc(fmt(r.created_at))},{key:'participant_id',label:'参与者'},{key:'reason',label:'原因'},{key:'before',label:'Before',render:r=>esc(valueText(r.before))},{key:'after',label:'After',render:r=>esc(valueText(r.after))}],p.promotion_history||[]))}</article></div></section>`}
function careEffectCharts(groups){const byType=new Map();groups.forEach(g=>{const item=byType.get(g.intervention_type)||{helpful:0,n:0};item.helpful+=Number(g.helpful_count||0);item.n+=Number(g.helpful_sample_count||0);byType.set(g.intervention_type,item)});const bars=[...byType.entries()].filter(([,v])=>v.n);const barChart=bars.length?`<div class="simple-bars">${bars.map(([label,v])=>`<div><span>${esc(label)} · n=${v.n}</span><i><b style="width:${(v.helpful/v.n)*100}%"></b></i><strong>${((v.helpful/v.n)*100).toFixed(1)}%</strong></div>`).join('')}</div>`:renderEmptyState('暂无 Helpful 反馈');const scatter=groups.filter(g=>g.sample_count>=3&&g.receptivity!=null&&g.helpful_rate!=null);const scatterChart=scatter.length?`<svg class="care-scatter" viewBox="0 0 440 240" role="img" aria-label="Receptivity 与 Helpful Rate 描述性散点">${scatter.map(g=>`<circle cx="${35+Number(g.receptivity)*370}" cy="${205-Number(g.helpful_rate)*170}" r="${Math.min(12,4+g.sample_count/2)}"><title>${esc(g.intervention_type)} · n=${g.sample_count}</title></circle>`).join('')}<line x1="35" y1="205" x2="420" y2="205"/><line x1="35" y1="25" x2="35" y2="205"/><text x="170" y="232">Receptivity（0–1）</text><text x="4" y="18">Helpful Rate</text></svg>`:renderEmptyState('样本不足，不绘图');const deltas=groups.filter(g=>g.sample_count>=3&&(g.observed_stress_change_30m!=null||g.observed_stress_change_60m!=null));const deltaChart=deltas.length?renderDataTable([{key:'intervention_type',label:'干预类型'},{key:'sample_count',label:'n'},{key:'observed_stress_change_30m',label:'30m ΔStress',render:r=>esc(numberText(r.observed_stress_change_30m))},{key:'observed_stress_change_60m',label:'60m ΔStress',render:r=>esc(numberText(r.observed_stress_change_60m))}],deltas):renderEmptyState('样本不足，不绘图');return `<div class="care-chart-grid"><section><h4>Helpful Rate（按干预类型）</h4>${barChart}</section><section><h4>Receptivity × Helpful Rate</h4><p class="muted">仅描述性散点，不拟合因果趋势。</p>${scatterChart}</section><section><h4>30m / 60m observed stress change</h4>${deltaChart}</section></div>`}
function careEffectView(){const d=state.careEffects||{};const s=d.summary||{};const groups=d.groups||[];const contract={schema_version:d.schema_version,analysis_type:d.analysis_type,causal_claim_allowed:d.causal_claim_allowed,mrt_runtime_enabled:d.mrt_runtime_enabled,mrt_rows_present:d.mrt_rows_present,date_start:d.date_start,date_end:d.date_end};const summary=`<div class="analysis-contract"><span>分析类型：观察性描述</span><span>因果声明：不允许</span><span>MRT：${d.mrt_runtime_enabled?'启用':'未启用'}</span><span>MRT 数据：${d.mrt_rows_present?'有':'无'}</span><span>分析窗口：${esc(d.date_start)} → ${esc(d.date_end)}</span><span>Schema：${esc(d.schema_version)}</span></div><div class="causal-note">该结果用于描述关联，不解释为因果效应。</div><section class="metric-grid compact-metrics">${metric('分组数',s.group_count??0)}${metric('总样本数',s.total_sample_count??0)}${metric('有帮助样本数',s.helpful_count??0)}${metric('总体 Helpful Rate',percentText(s.overall_helpful_rate))}${metric('30m 有效随访数',s.followup_30m_sample_count??0)}${metric('60m 有效随访数',s.followup_60m_sample_count??0)}${metric('平均 Receptivity',numberText(s.mean_receptivity))}</section>${renderDataTable([{key:'intervention_type',label:'干预类型'},{key:'stress_level',label:'压力层级'},{key:'workload',label:'Workload 层级'},{key:'time_of_day',label:'时段'},{key:'sample_count',label:'样本数'},{key:'helpful_count',label:'Helpful'},{key:'helpful_rate',label:'Helpful Rate',render:r=>esc(percentText(r.helpful_rate))},{key:'receptivity',label:'Receptivity',render:r=>esc(numberText(r.receptivity))},{key:'observed_stress_change_30m',label:'30m ΔStress',render:r=>esc(numberText(r.observed_stress_change_30m))},{key:'observed_stress_change_60m',label:'60m ΔStress',render:r=>esc(numberText(r.observed_stress_change_60m))},{key:'forecast_residual_30m',label:'30m Residual',render:r=>esc(numberText(r.forecast_residual_30m))},{key:'forecast_residual_60m',label:'60m Residual',render:r=>esc(numberText(r.forecast_residual_60m))},{key:'uncertainty',label:'95% CI',render:r=>esc(uncertaintyText(r.uncertainty?.helpful_rate))}],groups)}${careEffectCharts(groups)}`;return `<article class="card research-section"><div class="card-head"><div><p class="eyebrow">INTERVENTION EFFECT</p><h3>Care Effect（观察性描述）</h3></div>${renderViewToggle('careEffects')}</div>${(state.viewModes.careEffects||'summary')==='summary'?summary:(state.viewModes.careEffects==='fields'?renderKeyValueGrid(contract,{'schema_version':'Schema 版本','analysis_type':'分析类型','causal_claim_allowed':'允许因果声明','mrt_runtime_enabled':'MRT Runtime','mrt_rows_present':'MRT 数据','date_start':'开始日期','date_end':'结束日期'}):renderJsonDetails('careEffectsRaw',d))}</article>`}
function researchView(){const d=state.researchDashboard||{};const c=d.data_completeness||{};const f=d.forecast||{};const w=d.warning_care||{};const canWrite=['admin','superadmin'].includes(state.session.role);return `<div class="page-head"><div><p class="eyebrow">RESEARCH EVALUATION</p><h1>研究评估</h1><p class="muted">按固定日期窗口追踪数据完整性、预测误差、区间校准与 Care 效果。</p></div>${canWrite?'<button class="secondary" id="rebuild-matches">物化当前窗口匹配</button>':''}</div>${researchDateToolbar('research-filter')}${modelComparisonTable(state.modelComparison)}${careEffectView()}
  <section class="metric-grid">${metric('活跃用户',c.active_participants)}${metric('符合条件用户日',c.eligible_participant_days)}${metric('观测用户日',c.observed_days)}${metric('EMA 数',c.ema_count)}${metric('EMA 观测日率',c.ema_observed_day_rate==null?'—':`${(c.ema_observed_day_rate*100).toFixed(1)}%`)}${metric('Daily Review',c.daily_review_completion==null?'—':`${(c.daily_review_completion*100).toFixed(1)}%`)}${metric('日历覆盖',c.calendar_coverage==null?'—':`${(c.calendar_coverage*100).toFixed(1)}%`)}${metric('MAE',f.mae??'—')}${metric('RMSE',f.rmse??'—')}${metric('90% 区间覆盖',f.interval_90_coverage==null?'—':`${(f.interval_90_coverage*100).toFixed(1)}%`)}${metric('已发送预警',w.sent_count)}${metric('已抑制',w.suppressed_count)}${metric('有帮助反馈',w.helpful_feedback_rate==null?'—':`${(w.helpful_feedback_rate*100).toFixed(1)}%`)}</section>
  <div class="two-col"><article class="card"><div class="card-head"><div><h3>不可变数据集快照</h3><p class="muted">逐条冻结 Participant Membership、Observation、causal Forecast、Currentness、Calendar 表示和 Match Source，并生成 manifest hash。</p></div>${canWrite?'<button class="secondary" id="create-snapshot">创建当前窗口快照</button>':''}</div>${state.datasetSnapshots.map(s=>`<details><summary>${esc(s.id)} · ${esc(s.date_start)}–${esc(s.date_end)}</summary>${renderJsonDetails(`snapshot-${s.id}`,s)}</details>`).join('')||'<div class="empty">暂无快照</div>'}</article><article class="card"><h3>模型评估运行</h3>${canWrite?`<form id="evaluation-create">${renderFilterBar(`${renderSelect({name:'dataset_snapshot_id',label:'数据集快照',options:[{value:'',label:'选择数据集快照'},...state.datasetSnapshots.map(s=>({value:s.id,label:`${s.date_start}–${s.date_end} · ${s.id.slice(0,8)}`}))],required:true,note:'选择用于评估的不可变快照'})}${renderSelect({name:'evaluation_mode',label:'评估模式',value:'historical_online',options:[{value:'historical_online',label:'historical_online'}, {value:'offline_replay',label:'offline_replay（Rolling-Origin 模型族比较）'}],note:'当前选择的完整评估语义显示于此'})}${renderField({name:'model_version',label:'算法版本',placeholder:'历史 algorithm_version / 候选模型版本',required:true})}`,'filter-bar--research-run row-primary')}${renderFilterBar(`${renderField({name:'participant_code',label:'参与者代码',placeholder:'例如 P002（可选）',minWidth:true})}<div class="filter-action"><button class="primary">运行评估</button></div>`,'filter-bar--research-run row-secondary')}</form>`:''}${state.evaluationRuns.map(r=>`<details><summary>${esc(r.evaluation_mode)} · ${esc(r.model_version)} · ${esc(r.status)} · ${fmt(r.created_at)}</summary>${renderKeyValueGrid(r.metrics||{})}${renderJsonDetails(`evaluation-${r.id}`,r.metrics)}</details>`).join('')||'<div class="empty">暂无评估运行。</div>'}</article></div>${stage5View(canWrite)}`}
function dataQualityView(){const q=state.dataQuality||{items:[],counts:{}};return `<div class="page-head"><div><p class="eyebrow">DATA QUALITY</p><h1>数据质量</h1><p class="muted">缺失、迟到、回填、降级、语义拒绝、重复与时间异常的统一审计视图。</p></div></div><form id="quality-filter">${renderFilterBar(`${renderField({name:'date_start',label:'开始日期',type:'date',value:state.researchStart,required:true})}${renderField({name:'date_end',label:'结束日期',type:'date',value:state.researchEnd,required:true})}${renderField({name:'participant_code',label:'参与者代码',placeholder:'例如 P002（可选）',minWidth:true})}<div class="filter-action"><button class="primary">查询</button></div>`,'filter-bar--workload')}</form><article class="card"><div class="card-head"><h3>问题清单</h3><span>${q.items?.length||0} 条</span></div>${renderKeyValueGrid(q.counts||{})}<div class="table-wrap"><table><thead><tr><th>类型</th><th>用户</th><th>日期</th><th>详情</th></tr></thead><tbody>${(q.items||[]).map(i=>`<tr><td><span class="pill ${i.issue_type.includes('missing')||i.issue_type.includes('anomaly')?'bad':''}">${esc(i.issue_type)}</span></td><td>${esc(i.participant_code||i.participant_id)}</td><td>${esc(i.local_date)}</td><td>${esc(valueText(i.details))}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">当前窗口未发现数据质量问题</td></tr>'}</tbody></table></div>${renderJsonDetails('dataQualityRaw',q)}</article>`}
function participantResearchTabV2(){const l=state.longitudinal||{};const e=state.participantEvaluation||{};const m=e.metrics||{};const trends={stress_7d:l.stress_trend_7d,stress_14d:l.stress_trend_14d,workload_7d:l.workload_trend_7d,care_feedback:l.care_feedback};const residualRows=Object.entries(e.residual_diagnostics||{}).flatMap(([dimension,rows])=>(rows||[]).map(row=>({dimension,...row})));const interval={nominal_coverage:m.interval_nominal_coverage,empirical_coverage:m.interval_90_coverage,mean_interval_width:m.mean_interval_width,observed_peak_proxy_magnitude_error:m.observed_peak_proxy_magnitude_error,observed_peak_proxy_timing_error_minutes:m.observed_peak_proxy_timing_error_minutes,peak_proxy_day_count:m.peak_proxy_day_count,peak_proxy_mean_samples_per_day:m.peak_proxy_mean_samples_per_day};return `<section><div class="metric-grid">${metric('7日 EMA 观测日率',percentText(l.ema_observed_day_rate_7d))}${metric('14日 EMA 观测日率',percentText(l.ema_observed_day_rate_14d))}${metric('Daily Review',percentText(l.daily_review_adherence))}${metric('预警',l.warning_count??'暂无数据')}${metric('校准版本',l.calibration_version??'暂无')}${metric('匹配观测',m.sample_count??0)}${metric('MAE',m.mae??'暂无观测')}${metric('90% 区间覆盖',percentText(m.interval_90_coverage))}</div><div class="two-col"><article class="card"><h3>压力与负荷纵向变化</h3>${renderDataTable([{key:'date',label:'日期'},{key:'mean_stress',label:'平均压力'},{key:'ema_count',label:'EMA 数'}],l.stress_trend_14d||[])}${renderJsonDetails('participantTrends',trends)}</article><article class="card"><h3>残差分层诊断</h3>${renderComplexObject('residualDiagnostics',e.residual_diagnostics||{},renderDataTable([{key:'dimension',label:'维度'},{key:'group',label:'分组'},{key:'mean_residual',label:'平均残差'},{key:'mae',label:'MAE'},{key:'sample_count',label:'样本'}],residualRows))}</article></div><div class="two-col"><article class="card"><h3>参数历史</h3><p class="muted">S_star、reactivity、recovery、workload_gain 的估计、不确定性、样本量和验证状态。</p>${renderDataTable([{key:'version',label:'版本'},{key:'effective_from',label:'生效日期'},{key:'model_version',label:'模型'},{key:'validation_result',label:'验证状态'},{key:'sample_count',label:'样本'},{key:'parameters',label:'参数',render:r=>esc(valueText(r.parameters))}],l.parameter_history||[])}</article><article class="card"><h3>区间与观测峰值代理诊断</h3>${renderKeyValueGrid(interval)}</article></div><article class="card"><h3>Forecast–Observation 匹配</h3>${renderDataTable([{key:'observed_at',label:'观测时间',render:r=>esc(fmt(r.observed_at))},{key:'forecast_version',label:'Forecast'},{key:'predicted_stress',label:'预测'},{key:'actual_stress',label:'实际'},{key:'residual',label:'残差'}],e.matches||[],'暂无已物化匹配')}</article></section>`}
function incidentsView(){ return `<div class="page-head"><div><p class="eyebrow">ERROR CENTER</p><h1>异常中心</h1><p class="muted">仅呈现需要管理员处理的持久化运行事件。</p></div></div><article class="card"><div class="table-wrap"><table><thead><tr><th>时间</th><th>严重度</th><th>子系统</th><th>事件</th><th>摘要</th><th>错误</th></tr></thead><tbody>${state.incidents.map(i=>`<tr><td>${fmt(i.created_at)}</td><td><span class="pill ${i.severity==='error'?'bad':''}">${esc(i.severity)}</span></td><td>${esc(i.subsystem)}</td><td>${esc(i.event_name)}</td><td>${esc(i.summary)}</td><td>${esc(i.error_code||i.error_class||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无异常</td></tr>'}</tbody></table></div></article>`; }
function adminsView(){return `<div class="page-head"><div><p class="eyebrow">ACCESS CONTROL</p><h1>管理员</h1><p class="muted">仅 superadmin 可以新增账号或调整权限；环境账号始终保持最高权限。</p></div></div><article class="card"><form class="toolbar admin-create" id="admin-create"><input name="username" placeholder="新管理员用户名" required minlength="3"><input name="password" type="password" placeholder="初始密码（至少 10 位）" required minlength="10"><select name="role"><option value="viewer">viewer</option><option value="admin">admin</option><option value="superadmin">superadmin</option></select><button class="primary">新增管理员</button></form><div class="table-wrap"><table><thead><tr><th>用户名</th><th>角色</th><th>状态</th><th>环境根账号</th><th>最近登录</th><th>操作</th></tr></thead><tbody>${state.adminUsers.map(a=>`<tr><td>${esc(a.username)}</td><td>${esc(a.role)}</td><td>${esc(a.status)}</td><td>${a.is_environment_bootstrap?'是':'否'}</td><td>${fmt(a.last_login_at)}</td><td>${a.is_environment_bootstrap?'受保护':`<button class="secondary" data-admin-toggle="${a.id}" data-status="${a.status==='active'?'disabled':'active'}">${a.status==='active'?'停用':'启用'}</button>`}</td></tr>`).join('')}</tbody></table></div></article>`}
function render(){ viewDataRegistry.clear();if(!state.session){root.innerHTML=loginView(); bindLogin(); return;} let content=state.page==='dashboard'?dashboardView():state.page==='research'?researchView():state.page==='workload'?workloadView():state.page==='quality'?dataQualityView():state.page==='incidents'?incidentsView():state.page==='admins'?adminsView():state.selected?userDetail():participantsView(); root.innerHTML=shell(content); bind(); }
function bindLogin(){ document.querySelector('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.currentTarget);try{state.session=await api('/admin/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(data))});state.curveDate=state.session.business_date||localDateString();if(state.page==='research')await loadResearch();else if(state.page==='workload')await loadWorkload();else if(state.page==='quality')await loadQuality();else await loadDashboard();render()}catch(err){document.querySelector('#login-error').textContent=err.message}}); }
async function loadDashboard(){state.dashboard=await api('/admin/api/dashboard')}
async function loadResearch(){const query=`date_start=${encodeURIComponent(state.researchStart)}&date_end=${encodeURIComponent(state.researchEnd)}`;const [dashboard,snapshots,runs,comparison,parameterLearning,careEffects]=await Promise.all([api(`/admin/api/research/dashboard?${query}`),api('/admin/api/research/dataset-snapshots'),api('/admin/api/research/evaluation-runs'),api('/admin/api/research/model-comparison'),api('/admin/api/research/parameter-learning'),api(`/admin/api/research/care-effects?${query}`)]);state.researchDashboard=dashboard;state.datasetSnapshots=snapshots.items;state.evaluationRuns=runs.items;state.modelComparison=comparison;state.parameterLearning=parameterLearning;state.careEffects=careEffects}
async function loadWorkload(participantCode=state.workloadParticipantCode){state.workloadParticipantCode=participantCode||'';const query=`date_start=${encodeURIComponent(state.researchStart)}&date_end=${encodeURIComponent(state.researchEnd)}&participant_code=${encodeURIComponent(state.workloadParticipantCode)}`;state.workloadDashboard=await api(`/admin/api/research/workload?${query}`)}
async function loadQuality(participantCode=''){const query=`date_start=${encodeURIComponent(state.researchStart)}&date_end=${encodeURIComponent(state.researchEnd)}&participant_code=${encodeURIComponent(participantCode)}`;state.dataQuality=await api(`/admin/api/data-quality?${query}`)}
async function loadParticipants(search='',status=''){state.participants=await api(`/admin/api/participants?search=${encodeURIComponent(search)}&status=${encodeURIComponent(status)}`)}
async function openUser(code){const encoded=encodeURIComponent(code);[state.selected,state.participantOverview]=await Promise.all([api(`/admin/api/participants/${encoded}`),api(`/admin/api/participants/${encoded}/overview`)]);state.page='participants';state.tab='overview';state.curve=null;state.curveError='';render()}
async function loadTab(tab){state.tab=tab;const code=encodeURIComponent(state.selected.participant_code);if(tab==='overview')state.participantOverview=await api(`/admin/api/participants/${code}/overview`);if(tab==='research'){const query=`date_start=${encodeURIComponent(state.researchStart)}&date_end=${encodeURIComponent(state.researchEnd)}`;[state.longitudinal,state.participantEvaluation,state.participantModelComparison]=await Promise.all([api(`/admin/api/participants/${code}/longitudinal?through=${encodeURIComponent(state.researchEnd)}&days=14`),api(`/admin/api/participants/${code}/evaluation?${query}`),api(`/admin/api/participants/${code}/model-comparison`)])}if(tab==='messages')state.messages=(await api(`/admin/api/participants/${code}/messages`)).items;if(tab==='observations')state.observations=(await api(`/admin/api/participants/${code}/observations`)).items;if(tab==='calendar')state.calendars=(await api(`/admin/api/participants/${code}/calendar`)).items;if(tab==='forecast'){state.forecasts=(await api(`/admin/api/participants/${code}/forecasts`)).items;await loadCurve(false)}if(tab==='dailyreview')state.dailyReviews=(await api(`/admin/api/participants/${code}/daily-reviews`)).items;if(tab==='warnings')state.warnings=(await api(`/admin/api/participants/${code}/warnings`)).items;if(tab==='care'){[state.careTimeline,state.weeklyInsights]=await Promise.all([api(`/admin/api/participants/${code}/care-timeline`),api(`/admin/api/participants/${code}/weekly-insights?through=${encodeURIComponent(state.researchEnd)}`)])}render()}
async function loadCurve(shouldRender=true){const code=encodeURIComponent(state.selected.participant_code);state.curveError='';try{state.curve=await api(`/admin/api/participants/${code}/pressure-curve/${state.curveDate}`)}catch(error){state.curve=null;state.curveError=error.message}if(shouldRender)render()}
function bind(){ document.querySelectorAll('[data-view-key]').forEach(b=>b.onclick=()=>{state.viewModes[b.dataset.viewKey]=b.dataset.viewMode;render()});
  document.querySelectorAll('[data-described-select]').forEach(select=>select.onchange=()=>{const text=select.options[select.selectedIndex]?.text||select.value;select.title=text;const note=select.parentElement.querySelector('[data-select-current]');if(note)note.textContent=text});
  document.querySelectorAll('[data-copy-json]').forEach(b=>b.onclick=async()=>{const value=viewDataRegistry.get(b.dataset.copyJson);if(value===undefined)return;await navigator.clipboard.writeText(pretty(value));toast('JSON 已复制')});
  document.querySelectorAll('[data-dimension-mode]').forEach(b=>b.onclick=()=>{state.dimensionMode=b.dataset.dimensionMode;render()});
  document.querySelectorAll('[data-page]').forEach(b=>b.onclick=async()=>{state.page=b.dataset.page;state.selected=null;if(state.page==='dashboard')await loadDashboard();if(state.page==='research')await loadResearch();if(state.page==='workload')await loadWorkload();if(state.page==='quality')await loadQuality();if(state.page==='participants')await loadParticipants();if(state.page==='incidents')state.incidents=(await api('/admin/api/incidents')).items;if(state.page==='admins')state.adminUsers=(await api('/admin/api/admin-users')).items;render()});
  document.querySelector('#logout')?.addEventListener('click',async()=>{await api('/admin/api/logout',{method:'POST',body:'{}'});state.session=null;render()});
  document.querySelector('#refresh-dashboard')?.addEventListener('click',async()=>{await loadDashboard();toast('总览已更新')});
  document.querySelector('#participant-filter')?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.currentTarget);await loadParticipants(d.get('search'),d.get('status'));render()});
  document.querySelector('#research-filter')?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.currentTarget);state.researchStart=d.get('date_start');state.researchEnd=d.get('date_end');await loadResearch();render()});
  document.querySelector('#workload-filter')?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.currentTarget);state.researchStart=d.get('date_start');state.researchEnd=d.get('date_end');await loadWorkload(d.get('participant_code'));render()});
  document.querySelector('#quality-filter')?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.currentTarget);state.researchStart=d.get('date_start');state.researchEnd=d.get('date_end');await loadQuality(d.get('participant_code'));render()});
  document.querySelector('#create-snapshot')?.addEventListener('click',async()=>{await api('/admin/api/research/dataset-snapshots',{method:'POST',body:JSON.stringify({date_start:state.researchStart,date_end:state.researchEnd})});await loadResearch();toast('研究数据集快照已冻结')});
  document.querySelector('#rebuild-matches')?.addEventListener('click',async()=>{const query=`date_start=${encodeURIComponent(state.researchStart)}&date_end=${encodeURIComponent(state.researchEnd)}`;const result=await api(`/admin/api/research/matches/rebuild?${query}`,{method:'POST',body:'{}'});await loadResearch();toast(`匹配已物化：新增 ${result.created}，更新 ${result.updated}`)});
  document.querySelector('#evaluation-create')?.addEventListener('submit',async e=>{e.preventDefault();const value=Object.fromEntries(new FormData(e.currentTarget));await api('/admin/api/research/evaluation-runs',{method:'POST',body:JSON.stringify(value)});await loadResearch();toast('模型评估运行已完成')});
  document.querySelector('#parameter-learning-create')?.addEventListener('submit',async e=>{e.preventDefault();const value=Object.fromEntries(new FormData(e.currentTarget));await api('/admin/api/research/parameter-learning-runs',{method:'POST',body:JSON.stringify(value)});await loadResearch();toast('阶段 5 候选参数训练已完成')});
  document.querySelectorAll('[data-promote-parameter]').forEach(b=>b.onclick=async()=>{await api(`/admin/api/research/parameter-learning-runs/${b.dataset.promoteParameter}/promote`,{method:'POST',body:'{}'});await loadResearch();toast('候选参数已晋级为 Active')});
  document.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>openUser(b.dataset.user));document.querySelector('#back-users')?.addEventListener('click',()=>{state.selected=null;render()});
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>loadTab(b.dataset.tab));document.querySelectorAll('[data-message]').forEach(b=>b.onclick=async()=>{const m=await api(`/admin/api/messages/${encodeURIComponent(b.dataset.message)}`);alert(pretty(m))});
  document.querySelector('#curve-date')?.addEventListener('change',e=>state.curveDate=e.target.value);document.querySelector('#load-curve')?.addEventListener('click',loadCurve);
  const shift=n=>{state.curveDate=shiftDate(state.curveDate,n);loadCurve()};document.querySelector('#prev-day')?.addEventListener('click',()=>shift(-1));document.querySelector('#next-day')?.addEventListener('click',()=>shift(1));
  document.querySelector('#refresh-forecast')?.addEventListener('click',async()=>{const code=encodeURIComponent(state.selected.participant_code);await api(`/admin/api/participants/${code}/forecasts/${state.curveDate}/refresh`,{method:'POST',body:'{}'});await loadCurve();toast('Forecast 已刷新')});
  document.querySelector('#rebuild-review')?.addEventListener('click',async()=>{const code=encodeURIComponent(state.selected.participant_code);await api(`/admin/api/participants/${code}/retrospective-curve/${state.curveDate}/rebuild`,{method:'POST',body:'{}'});toast('回顾估计已重建')});
  document.querySelector('#admin-create')?.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));await api('/admin/api/admin-users',{method:'POST',body:JSON.stringify(data)});state.adminUsers=(await api('/admin/api/admin-users')).items;toast('管理员已新增')});
  document.querySelectorAll('[data-admin-toggle]').forEach(b=>b.onclick=async()=>{await api(`/admin/api/admin-users/${b.dataset.adminToggle}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status})});state.adminUsers=(await api('/admin/api/admin-users')).items;render()}); }
restore();
